#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int a, b, w;
} Edge;

static int *parent = NULL;

static int find_set(int x)
{
    if (parent[x] != x)
        parent[x] = find_set(parent[x]);
    return parent[x];
}

static void union_set(int x, int y)
{
    int px = find_set(x);
    int py = find_set(y);
    if (px != py)
        parent[px] = py;
}

static int cmp_edge(const void *p1, const void *p2)
{
    const Edge *e1 = (const Edge *)p1;
    const Edge *e2 = (const Edge *)p2;
    if (e1->w != e2->w)
        return e1->w - e2->w;
    if (e1->a != e2->a)
        return e1->a - e2->a;
    return e1->b - e2->b;
}

int main(int argc, char *argv[])
{
    if (argc != 2) {
        puts("INVALID_ARGS");
        return 0;
    }
    char *endptr;
    long n_long = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || n_long <= 0) {
        puts("INVALID_ARGS");
        return 0;
    }
    int n = (int)n_long;

    Edge *edges = NULL;
    size_t edges_cap = 0, edges_cnt = 0;
    for (;;) {
        int a, b, w;
        int rc = scanf("%d %d %d", &a, &b, &w);
        if (rc == EOF || rc < 3)
            break;
        if (edges_cnt == edges_cap) {
            size_t new_cap = edges_cap ? edges_cap * 2 : 16;
            Edge *tmp = realloc(edges, new_cap * sizeof *tmp);
            if (!tmp) {
                perror("realloc");
                free(edges);
                return 1;
            }
            edges = tmp;
            edges_cap = new_cap;
        }
        edges[edges_cnt++] = (Edge){a, b, w};
    }

    parent = calloc((size_t)n, sizeof *parent);
    if (!parent) {
        perror("calloc");
        free(edges);
        return 1;
    }
    for (int i = 0; i < n; ++i)
        parent[i] = i;

    qsort(edges, edges_cnt, sizeof *edges, cmp_edge);

    int *mst_a = malloc(n * sizeof *mst_a);
    int *mst_b = malloc(n * sizeof *mst_b);
    if (!mst_a || !mst_b) {
        perror("malloc");
        free(edges);
        free(parent);
        free(mst_a);
        free(mst_b);
        return 1;
    }
    int mst_edges = 0;
    int total_weight = 0;

    for (size_t i = 0; i < edges_cnt && mst_edges < n - 1; ++i) {
        int u = edges[i].a;
        int v = edges[i].b;
        if (find_set(u) != find_set(v)) {
            union_set(u, v);
            mst_a[mst_edges] = u;
            mst_b[mst_edges] = v;
            total_weight += edges[i].w;
            ++mst_edges;
        }
    }

    if (mst_edges != n - 1) {
        puts("DISCONNECTED");
    } else {
        printf("weight=%d edges=", total_weight);
        for (int i = 0; i < mst_edges; ++i) {
            if (i > 0)
                putchar(',');
            printf("%d-%d", mst_a[i], mst_b[i]);
        }
        putchar('\n');
    }

    free(edges);
    free(parent);
    free(mst_a);
    free(mst_b);
    return 0;
}
